#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <random>
#include <string>
#include <vector>
using U=uint64_t;
std::string artifactPrefix;
struct G{int a,b;bool op;};struct C{std::array<G,96>g;int out;};
int ni,ng,budget,np,nn,mp,ml,rp,rl,nt;U target,tmask,dmask;std::array<U,128> iv;std::vector<int> rows,original;std::vector<C> seeds;int best=1000;bool found=false;int branchTarget=0;std::vector<unsigned> branchMasks;auto begun=std::chrono::steady_clock::now();
int secs(){return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now()-begun).count();}
U calc(U a,U b,bool op){return op?(a&b&tmask)|((a&(((b>>nt)&3)<<(nt+2)))|(b&(((a>>nt)&3)<<(nt+2)))):a|b;}
U eval(const C&c){auto v=iv;for(int i=0;i<ng;i++)v[ni+i]=calc(v[c.g[i].a],v[c.g[i].b],c.g[i].op);return v[c.out];}
std::array<bool,128> used(const C&c){std::array<bool,128>u{};u[c.out]=true;for(int i=ng-1;i>=0;i--)if(u[ni+i])u[c.g[i].a]=u[c.g[i].b]=true;return u;}
int active(const C&c){auto u=used(c);int n=0;for(int i=0;i<ng;i++)n+=u[ni+i];return n;}
C supported(C c){auto v=iv;for(int i=0;i<ng;i++){U z=calc(v[c.g[i].a],v[c.g[i].b],c.g[i].op);if(!(z&target)){c.g[i]={rp,rl,true};z=calc(v[rp],v[rl],true);}v[ni+i]=z;}return c;}

C compress(C c){U before=eval(c);auto v=iv;std::array<int,128>map;std::array<int,256>rep;std::array<U,256>key;rep.fill(-1);auto intern=[&](U z,int candidate){unsigned h=(z*11400714819323198485ull)>>56;while(rep[h]!=-1&&key[h]!=z)h=(h+1)&255;if(rep[h]!=-1)return rep[h];key[h]=z;rep[h]=candidate;return candidate;};for(int i=0;i<ni;i++){map[i]=i;if(calc(v[i],v[i],true)==v[i])intern(v[i],i);}for(int i=0;i<ng;i++){int a=map[c.g[i].a],b=map[c.g[i].b];U z=calc(v[a],v[b],c.g[i].op);c.g[i].a=a;c.g[i].b=b;v[ni+i]=z;if(a==b){if(z!=v[a]){std::cerr<<"non-idempotent alias collision\n";std::exit(2);}map[ni+i]=a;}else if(calc(z,z,true)==z)map[ni+i]=intern(z,ni+i);else map[ni+i]=ni+i;}c.out=map[c.out];auto u=used(c);for(int i=0;i<ng;i++)if(c.g[i].a==c.g[i].b){if(u[ni+i]){std::cerr<<"active self gate after compression\n";std::exit(2);}c.g[i].b=(c.g[i].b+1)%(ni+i);}if(eval(c)!=before){std::cerr<<"boundary/trace compression mismatch\n";std::exit(2);}return c;}
C normalize(C c){std::array<int,128>map;for(int i=0;i<ni;i++)map[i]=i;for(int i=0;i<ng;i++){int a=map[c.g[i].a],b=map[c.g[i].b];c.g[i].a=a;c.g[i].b=b;map[ni+i]=a==b?a:ni+i;}c.out=map[c.out];return c;}
void save(const C&c,U v,const std::string&path){auto u=used(c);std::array<int,128>map;for(int i=0;i<ni;i++)map[i]=i;int n=ni;for(int i=0;i<ng;i++)if(u[ni+i])map[ni+i]=n++;std::ofstream f(path);f<<"{\n\"inputs\":"<<ni<<",\"size\":"<<n-ni<<",\"output\":"<<map[c.out]<<",\"marked_inputs\":["<<mp<<","<<ml<<"],\n\"original_inputs\":[";for(int i=0;i<ni;i++){if(i)f<<",";f<<original[i];}f<<"],\n\"failed_bits\":[";bool first=true;for(int i=0;i<nt+4;i++)if((v^target)&(U(1)<<i)){if(!first)f<<",";first=false;f<<i;}f<<"],\n\"failed_assignments\":[";first=true;for(int i=0;i<nt+2;i++)if((v^target)&(U(1)<<i)){if(!first)f<<",";first=false;f<<"{\"bit\":"<<i<<",\"mask\":"<<rows[i]<<"}";}f<<"],\n\"gates\":[\n";first=true;for(int i=0;i<ng;i++)if(u[ni+i]){if(!first)f<<",\n";first=false;f<<"[\""<<(c.g[i].op?"and":"or")<<"\","<<map[c.g[i].a]<<","<<map[c.g[i].b]<<"]";}f<<"\n]}\n";}
void report(const C&c,U v,uint64_t it){int errs=__builtin_popcountll(v^target);if(errs>1)return;int n=active(c);if(!errs&&n<best){best=n;save(c,v,artifactPrefix+"-best.json");std::cout<<"BEST t="<<secs()<<" it="<<it<<" gates="<<n<<std::endl;if(n<=budget)found=true;}if(errs==1&&n<=budget){int bit=__builtin_ctzll(v^target);static std::array<int,64>bn=[](){std::array<int,64>x;x.fill(1000);return x;}();if(n<bn[bit]){bn[bit]=n;std::string path=artifactPrefix+"-near-"+std::to_string(bit)+".json";save(c,v,path);std::cout<<"NEAR t="<<secs()<<" it="<<it<<" gates="<<n<<" bit="<<bit<<std::endl;}}}
C seed(std::mt19937_64&r,int mode){C c{};for(int i=0;i<ng;i++){c.g[i]={int(r()%(ni+i)),int(r()%(ni+i)),bool(r()%2)};if(c.g[i].a==c.g[i].b)c.g[i].b=(c.g[i].b+1)%(ni+i);}auto old=seeds[r()%seeds.size()];std::array<int,128>map;for(int i=0;i<ni;i++)map[i]=i;int ptr=0;for(int i=0;i<budget+1;i++){c.g[ptr]={map[old.g[i].a],map[old.g[i].b],old.g[i].op};map[ni+i]=ni+ptr++;if(ptr+(budget-i)<ng&&r()%2)ptr++;}c.out=map[old.out];c=supported(c);if(mode==0)return c;C b=c;int bs=1000000,ties=0;auto u=used(c);for(int rem=0;rem<ng;rem++)if(u[ni+rem])for(int rep=0;rep<ni+rem;rep++){C q=c;for(int j=rem+1;j<ng;j++){if(q.g[j].a==ni+rem)q.g[j].a=rep;if(q.g[j].b==ni+rem)q.g[j].b=rep;}if(q.out==ni+rem)q.out=rep;q=normalize(q);if(active(q)>budget)continue;U v=eval(q);int pe=__builtin_popcountll((v^target)&target),ne=__builtin_popcountll(v&(((U(1)<<nt)-1)^target)),de=__builtin_popcountll(v&(dmask|(U(3)<<nt)));int s=mode==1?pe*1000+ne*4+de*1000:(pe+ne)*4+de*3;if(s<bs){bs=s;ties=1;b=q;}else if(s==bs&&r()%++ties==0)b=q;}for(int i=0;i<ng;i++)if(b.g[i].a==b.g[i].b)b.g[i].b=(b.g[i].b+1)%(ni+i);return supported(b);}
void mutate(C&c,std::mt19937_64&r){int count=r()%100<85?1:2+r()%6;for(int k=0;k<count;k++){int z=r()%(3*ng+1);if(z==3*ng){c.out=r()%(ni+ng);continue;}int i=z/3,sel=z%3;if(!sel)c.g[i].a=r()%(ni+i);else if(sel==1)c.g[i].b=r()%(ni+i);else c.g[i].op=!c.g[i].op;if(c.g[i].a==c.g[i].b)c.g[i].b=(c.g[i].b+1)%(ni+i);}}
struct Shape{unsigned eligible=0;int positive=0,zero=0,comparable=0;};
Shape shape(const C&c){auto u=used(c);std::array<unsigned,128>sup{};std::array<int,128>fan{};auto v=iv;for(int i=0;i<ni;i++)sup[i]=1u<<i;U nmask=((U(1)<<nt)-1)^target;Shape sh;for(int i=0;i<ng;i++){auto g=c.g[i];sup[ni+i]=g.op?sup[g.a]&sup[g.b]:sup[g.a]|sup[g.b];v[ni+i]=calc(v[g.a],v[g.b],g.op);if(u[ni+i]){fan[g.a]++;fan[g.b]++;U m=g.op?nmask:target,a=v[g.a]&m,b=v[g.b]&m;if(!(a&~b)||!(b&~a))sh.comparable++;}}for(int i=0;i<ni+ng;i++)if(u[i]&&fan[i]>1){if(sup[i]){sh.positive+=fan[i]-1;sh.eligible|=sup[i];}else sh.zero+=fan[i]-1;}return sh;}
double score(const C&c,U v,int mode){int n=active(c);int pe=__builtin_popcountll((v^target)&target),ne=__builtin_popcountll(v&(((U(1)<<nt)-1)^target)),de=__builtin_popcountll(v&(dmask|(U(3)<<nt)));auto sh=shape(c);int p=__builtin_popcount(sh.eligible),points=__builtin_popcount(sh.eligible&127u),lines=__builtin_popcount(sh.eligible>>7);static std::array<std::array<int,32>,15> frontier=[](){std::array<std::array<int,32>,15>x;for(auto&a:x)a.fill(1000);return x;}();if(n<=budget&&de==0&&p>=8&&sh.zero<32&&pe+ne<frontier[p][sh.zero]){frontier[p][sh.zero]=pe+ne;save(c,v,artifactPrefix+"-frontier-p"+std::to_string(p)+"-bz"+std::to_string(sh.zero)+".json");std::cout<<"FRONTIER t="<<secs()<<" gates="<<n<<" p="<<p<<" Bzero="<<sh.zero<<" poserr="<<pe<<" negerr="<<ne<<std::endl;}double structural=0;if(mode==0)structural=__builtin_popcount(sh.eligible^branchMasks[branchTarget]);else if(mode==1){int dist=14;for(auto m:branchMasks)dist=std::min(dist,__builtin_popcount(sh.eligible^m));structural=dist;}else structural=std::abs(p-10)+std::max(0,points-6)+std::max(0,lines-6);structural+=.2*sh.comparable;if(mode==0)return(pe+ne)*6+de*4+std::max(0,n-budget)*5+structural*2+n*.01;if(mode==1)return pe*12+ne*3+de*5+std::max(0,n-budget)*6+structural*2+n*.01;return(pe+ne)*4+de*3+std::max(0,n-budget)*5+structural*1.5+n*.01;}

int main(int argc,char**argv){artifactPrefix=argv[3];std::ifstream f(argv[1]);int ns;f>>ni>>ng>>budget>>np>>nn>>ns>>mp>>ml>>rp>>rl;nt=np+nn;target=(U(1)<<np)-1;tmask=(U(1)<<(nt+2))-1;dmask=U(3)<<(nt+2);for(int i=0,x;i<ni;i++){f>>x;original.push_back(x);}for(int i=0,x;i<nt;i++){f>>x;rows.push_back(x);}rows.push_back(1<<mp);rows.push_back(1<<ml);for(int i=0;i<ni;i++)for(int j=0;j<int(rows.size());j++)if(rows[j]>>i&1)iv[i]|=U(1)<<j;iv[ml]|=U(1)<<(nt+2);iv[mp]|=U(1)<<(nt+3);for(int l=0;l<7;l++){unsigned pm=0;for(int j=0;j<np;j++){int row=rows[j];if(row&(1<<(7+l)))pm|=row&127;}branchMasks.push_back(pm|(((127u^(1u<<l)))<<7));}for(int p=0;p<7;p++){unsigned lm=0;for(int j=0;j<np;j++){int row=rows[j];if(row&(1<<p))lm|=(row>>7)&127;}branchMasks.push_back((127u^(1u<<p))|(lm<<7));}for(int k=0;k<ns;k++){C c{};int m;f>>m>>c.out;for(int i=0;i<m;i++){int op;f>>op>>c.g[i].a>>c.g[i].b;c.g[i].op=op;}seeds.push_back(c);}for(const C&old:seeds){C c{};for(int i=0;i<ng;i++)c.g[i]={rp,rl,true};for(int i=0;i<budget+1;i++)c.g[i]=old.g[i];c.out=old.out;c=compress(supported(c));report(c,eval(c),0);}int duration=argc>2?std::stoi(argv[2]):900;std::mt19937_64 r(928371645);uint64_t it=0;int cycle=0;while(!found&&secs()<duration){int mode=cycle++%3;branchTarget=r()%branchMasks.size();C cur=compress(seed(r,mode));U v=eval(cur);double s=score(cur,v,mode);report(cur,v,it);for(int j=0;j<1500000&&!found&&secs()<duration;j++,it++){C next=cur;mutate(next,r);next=compress(supported(next));U nv=eval(next);report(next,nv,it);double ns=score(next,nv,mode);double temp=(mode==1?3.0:3.5)*(1-double(j%150000)/150000);bool accept=ns<=s;if(!accept&&temp>1e-6)accept=std::generate_canonical<double,32>(r)<std::exp((s-ns)/temp);if(accept){cur=next;v=nv;s=ns;}if(j%1000000==0)std::cout<<"PROGRESS t="<<secs()<<" it="<<it<<" mode="<<mode<<" score="<<s<<" best="<<best<<" eligible="<<shape(cur).eligible<<" Bplus="<<shape(cur).positive<<" Bzero="<<shape(cur).zero<<std::endl;}}std::cout<<"DONE t="<<secs()<<" iterations="<<it<<" best="<<best<<std::endl;}
